import { useState } from "react";
import { useNavigate } from "react-router-dom";
import AuthLayout from "../../components/AuthLayout";
import { canSubmitSignInForm } from "../../utils/accountValidation";

const GoogleIcon = () => (
  <svg width="18" height="18" viewBox="0 0 24 24">
    <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>
    <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/>
    <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l3.66-2.84z"/>
    <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/>
  </svg>
);

const leftContent = (
  <div>
    <p className="text-[11px] tracking-widest text-white/50 uppercase mb-2">WELCOME BACK</p>
    <h2 className="font-serif text-4xl font-normal text-white leading-snug mb-6">
      Your network<br />is waiting<br /><em>for you.</em>
    </h2>
    <p className="text-sm text-white/70 leading-relaxed mb-8">
      Sign in to access your dashboard, track applications, manage job posts,
      and connect with talent across all 58 wilayas.
    </p>
    <div className="flex gap-3">
      {[{ n: "58", l: "Wilayas covered" }, { n: "∞", l: "Job & freelance posts" }, { n: "1st", l: "Verified DZ network" }].map((s) => (
        <div key={s.l} className="flex-1 bg-white/10 rounded-xl p-3">
          <p className="font-serif text-xl text-white">{s.n}</p>
          <p className="text-[11px] text-white/50 mt-1">{s.l}</p>
        </div>
      ))}
    </div>
  </div>
);

export default function SignInPage() {
  const navigate = useNavigate();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const canSignIn = canSubmitSignInForm({ email, password });

  const handleSignIn = () => {
    if (!canSignIn) return;
    navigate("/dashboard");
  };

  return (
    <AuthLayout leftContent={leftContent} leftBg="bg-gradient-to-br from-red to-[#2d1b3d]">
      <h2 className="font-serif text-3xl font-normal mb-1">Good to have<br />you back.</h2>
      <p className="text-sm text-gray-500 mb-7">Enter your credentials to continue.</p>

      <label className="block text-sm font-medium mb-1">Email Address</label>
      <input
        type="email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        className="w-full px-4 py-3 rounded-xl border border-gray-200 bg-cream text-sm mb-4 outline-none focus:border-navy focus:bg-white"
        placeholder="you@example.com"
      />

      <label className="block text-sm font-medium mb-1">Password</label>
      <input
        type="password"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        className="w-full px-4 py-3 rounded-xl border border-gray-200 bg-cream text-sm mb-1 outline-none focus:border-navy focus:bg-white"
        placeholder="Your password"
      />
      <p className="text-xs text-gray-400 mb-3">At least 8 characters</p>

      <div className="flex justify-between items-center mb-5">
        <label className="flex items-center gap-2 text-sm text-gray-500 cursor-pointer">
          <input type="checkbox" /> Remember me
        </label>
        <span className="text-sm text-navy underline cursor-pointer" onClick={() => navigate("/forgot-password")}>Forgot password?</span>
      </div>

      <div className="relative flex items-center justify-center mb-4">
        <div className="absolute w-full h-px bg-gray-200" />
        <span className="relative bg-cream px-3 text-xs text-gray-400">Or continue with</span>
      </div>

      <div className="flex gap-3 mb-4">
        <button className="flex-1 flex items-center justify-center gap-2 py-2.5 border border-gray-200 rounded-xl text-sm bg-white hover:bg-cream transition-all"><GoogleIcon /> Google</button>
        <button className="flex-1 flex items-center justify-center gap-2 py-2.5 border border-gray-200 rounded-xl text-sm bg-white hover:bg-cream transition-all">🍎 Apple</button>
      </div>

      <button
        type="button"
        disabled={!canSignIn}
        onClick={handleSignIn}
        className={`w-full py-3.5 rounded-full text-sm font-medium transition-all
          ${canSignIn
            ? "bg-red text-white hover:bg-red-dark"
            : "bg-red/40 text-white/80 cursor-not-allowed"}`}
      >
        Sign in →
      </button>

      <p className="text-sm text-gray-500 text-center mt-4">
        Don't have an account?{" "}
        <span className="text-navy underline cursor-pointer" onClick={() => navigate("/")}>Create one</span>
      </p>
    </AuthLayout>
  );
}
